  2		// AC: @web-dashboard ac-4, ac-5, ac-9, ac-10, ac-33
  3		// AC: @multi-directory-daemon ac-27 - Reload on project change
  4		// AC: @gh-pages-export ac-16 - Disable Start Task in static mode
  5		import { page } from '$app/stores';
  6		import { base } from '$app/paths';
  7		import { onMount, onDestroy, flushSync } from 'svelte';
  8		import type { TaskSummary, TaskDetail, BroadcastEvent } from '@kynetic-ai/shared';
  9		import TaskFilters from '$lib/components/TaskFilters.svelte';
 10		import TaskList from '$lib/components/TaskList.svelte';
 11		import { fetchTasks, fetchTask, startTask, addTaskNote } from '$lib/api';
 12		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 13		import { isStaticMode, ReadOnlyModeError } from '$lib/stores/mode.svelte';
 14		import { Button } from '$lib/components/ui/button';
 15		import { Badge } from '$lib/components/ui/badge';
 16		import { Textarea } from '$lib/components/ui/textarea';
 17		import { Separator } from '$lib/components/ui/separator';
 18		import * as Tooltip from '$lib/components/ui/tooltip';
 19		import XIcon from '@lucide/svelte/icons/x';
 20		import { getProjectVersion } from '$lib/stores/project.svelte';
 21	
 22		let tasks = $state<TaskSummary[]>([]);
 23		let total = $state(0);
 24		let loading = $state(true);
 25		let error = $state('');
 26		let updatedTaskIds = $state<Set<string>>(new Set());
 27	
 28		// Use $state with an object for panel state to ensure deep reactivity
 29		let panel = $state<{ open: boolean; task: TaskDetail | null }>({
 30			open: false,
 31			task: null
 32		});
 33	
 34		let noteContent = $state('');
 35		let isSubmitting = $state(false);
 36		let panelError = $state('');
 37	
 38		// Reactive: re-fetch when URL params change
 39		let filterParams = $derived({
 40			status: $page.url.searchParams.get('status') || undefined,
 41			type: $page.url.searchParams.get('type') || undefined,
 42			tag: $page.url.searchParams.get('tag') || undefined,
 43			assignee: $page.url.searchParams.get('assignee') || undefined,
 44			automation: $page.url.searchParams.get('automation') || undefined,
 45			plan: $page.url.searchParams.get('plan') || undefined,
 46			limit: 50,
 47			offset: 0
 48		});
 49	
 50		// Track the last processed ref to avoid infinite loops
 51		let lastProcessedRef = $state('');
 52	
 53		$effect(() => {
 54			// Re-fetch when filterParams changes - explicitly access all properties for dependency tracking
 55			const { status, type, tag, assignee, automation, plan, limit, offset } = filterParams;
 56			loadTasks();
 57		});
 58	
 59		// AC: @multi-directory-daemon ac-27 - Reload data when project changes
 60		$effect(() => {
 61			const version = getProjectVersion();
 62			if (version > 0) {
 63				// Only reload if version has been incremented (not on initial load)
 64				loadTasks();
 65			}
 66		});
 67	
 68		// AC: Open task detail when URL has ref param
 69		$effect(() => {
 70			const urlRef = $page.url.searchParams.get('ref');
 71			if (urlRef && urlRef !== lastProcessedRef) {
 72				lastProcessedRef = urlRef;
 73				handleSelectTask(urlRef);
 74			}
 75		});
 76	
 77		async function loadTasks() {
 78			loading = true;
 79			error = '';
 80	
 81			try {
 82				const response = await fetchTasks(filterParams);
 83				tasks = response.items;
 84				total = response.total;
 85			} catch (err) {
 86				error = err instanceof Error ? err.message : 'Failed to load tasks';
 87				console.error('Error loading tasks:', err);
 88			} finally {
 89				loading = false;
 90			}
 91		}
 92	
 93		async function handleSelectTask(taskId: string) {
 94			console.log('[TasksPage] handleSelectTask called for:', taskId);
 95			try {
 96				console.log('[TasksPage] Fetching task details...');
 97				const task = await fetchTask(taskId);
 98				console.log('[TasksPage] Task fetched:', task?.title);
 99				// Update panel state using flushSync to ensure synchronous DOM update
100				flushSync(() => {
101					panel.task = task;
102					panel.open = true;
103				});
104				console.log('[TasksPage] panel.open set to true, panel.task:', panel.task?.title);
105			} catch (err) {
106				error = err instanceof Error ? err.message : 'Failed to load task details';
107				console.error('[TasksPage] Error loading task:', err);
108			}
109		}
