 43			url.searchParams.set('ref', event.detail);
 44			window.history.pushState({}, '', url);
 45		}
 46	
 47	
 48		// Clear URL param when detail panel closes via bind:open
 49		$effect(() => {
 50			if (!detailOpen && selectedRef) {
 51				selectedRef = null;
 52				const url = new URL(window.location.href);
 53				url.searchParams.delete('ref');
 54				window.history.pushState({}, '', url);
 55			}
 56		});
 57	
 58		// React to URL ref param changes (handles both initial load and navigation)
 59		$effect(() => {
 60			const urlRef = $page.url.searchParams.get('ref');
 61			if (urlRef && urlRef !== selectedRef) {
 62				selectedRef = urlRef;
 63				detailOpen = true;
 64			}
 65		});
 66	
 67		onMount(() => {
 68			loadItems();
 69		});
 70	
 71		// Reload when plan filter changes (e.g. navigating from plans page)
 72		$effect(() => {
 73			const _plan = planFilter;
 74			loadItems();
 75		});
 76	
 77		// AC: @multi-directory-daemon ac-27 - Reload data when project changes
